package com.aiagent.admin.catalog;
import com.aiagent.admin.managed.*;
import com.aiagent.core.search.*;
import com.aiagent.core.deployment.CatalogSource;
import com.aiagent.domain.search.QueryDslBuilder;
import com.aiagent.domain.authz.ActionType;
import com.aiagent.support.time.*;
import com.querydsl.core.types.dsl.PathBuilder;
import com.querydsl.jpa.impl.JPAQueryFactory;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)
public class CatalogQueryService {
 private static final PathBuilder<CatalogRecord> R=new PathBuilder<>(CatalogRecord.class,"catalog");
 public record Filter(String dataSourceId,String businessName,String objectType){}
 public record Detail(Map<String,Object> row,Map<String,Object> values,Map<String,Object> dependencies){}
 private final JPAQueryFactory query;private final QueryDslBuilder builder;private final JdbcTemplate jdbc;private final CatalogService owner;private final CatalogAccess access;private final CatalogSource source;private final BusinessCalendar clock;
 public CatalogQueryService(JPAQueryFactory query,QueryDslBuilder builder,DataSource db,CatalogService owner,CatalogAccess access,CatalogSource source,BusinessCalendar clock){this.query=query;this.builder=builder;jdbc=new JdbcTemplate(db);this.owner=owner;this.access=access;this.source=source;this.clock=clock;}
 private QuerySpec spec(){var b=QuerySpec.of("catalog").from(R).col("id",R.getNumber("id",Long.class)).sortable().col("catalogId",R.getNumber("id",Long.class)).sortable().col("dataSourceId",R.getNumber("dataSourceId",Long.class)).sortable();for(String f:List.of("businessName","objectType","objectName","schemaName","databaseName","lifecycle"))b.col(f,R.getString(f)).sortable();return b.col("appliedAt",R.getDateTime("appliedAt",java.time.Instant.class)).sortable().defaultSort("businessName",SortDir.asc).pk(R.getNumber("id",Long.class)).build();}
 public PageResponse<Map<String,Object>> getList(SearchRequest<Filter> r){access.require(ActionType.READ);var c=new ArrayList<>(r.conditionsOrEmpty());if(r.params()!=null){var p=r.params();if(p.dataSourceId()!=null)c.add(new Condition("dataSourceId",Op.eq,p.dataSourceId()));if(p.businessName()!=null)c.add(new Condition("businessName",Op.contains,p.businessName()));if(p.objectType()!=null)c.add(new Condition("objectType",Op.eq,p.objectType()));}var built=builder.build(new SearchRequest<>(c,r.sorts(),r.page(),null),spec(),PageMode.offset);var rows=built.apply(query.select(R)).fetch().stream().map(this::row).toList();Long count=built.count(query).fetchOne();return built.respond(rows,count==null?0:count);}
 private Map<String,Object> row(CatalogRecord r){var v=new LinkedHashMap<String,Object>();v.put("id",r.id.toString());v.put("catalogId",r.id.toString());v.put("dataSourceId",r.dataSourceId.toString());v.put("serverName",r.serverName);v.put("databaseName",r.databaseName);v.put("schemaName",r.schemaName);v.put("objectName",r.objectName);v.put("objectType",r.objectType);v.put("businessName",r.businessName);v.put("useYn",Character.valueOf('Y').equals(r.useYn));v.put("revision",r.revision.toString());v.put("appliedAt",r.appliedAt);v.put("regId",r.regId);v.put("regDtm",r.regDtm);return v;}
 CatalogRecord root(String id){return Optional.ofNullable(query.selectFrom(R).where(R.getNumber("id",Long.class).eq(ManagedCommand.positive(id))).fetchOne()).orElseThrow(ManagedErrorCode.REFERENCE_CONFLICT::failure);}
 public Detail getOne(String id){access.require(ActionType.READ);var r=root(id);var values=owner.values(id);var dependencies=new LinkedHashMap<String,Object>();dependencies.put("review",jdbc.queryForMap("SELECT REVIEWER_ID AS \"reviewerId\",REVIEWED_DTM AS \"reviewedAt\" FROM AI_ADMIN_CATALOG_CONTENT WHERE CATALOG_ID=?",r.id));dependencies.put("columnReviews",jdbc.queryForList("SELECT COLUMN_ID::text AS \"columnId\",REVIEWER_ID AS \"reviewerId\",REVIEWED_DTM AS \"reviewedAt\",VALUE_REVIEWER_ID AS \"valueReviewerId\",VALUE_REVIEWED_DTM AS \"valueReviewedAt\" FROM AI_ADMIN_CATALOG_COLUMN WHERE CATALOG_ID=?",r.id));dependencies.put("groupCandidates",jdbc.query("SELECT U.GROUP_ID,U.GROUP_NM FROM AI_ADMIN_DATA_SOURCE_GROUP G JOIN AI_ADMIN_USER_GROUP U ON U.GROUP_ID=G.GROUP_ID WHERE G.DATA_SOURCE_ID=? AND G.ACTIVE_YN='Y' ORDER BY U.GROUP_NM,U.GROUP_ID",(rs,n)->Map.of("groupId",rs.getString(1),"groupName",rs.getString(2)),r.dataSourceId));for(String f:List.of("references","relations","constraints"))dependencies.put(f,Map.of("state","NOT_CONNECTED","rows",List.of()));if(jdbc.queryForObject("SELECT COUNT(*) FROM AI_ADMIN_CATALOG WHERE CATALOG_ID=? AND REVISION=?",Long.class,r.id,r.revision)!=1)throw ManagedErrorCode.REVISION_CONFLICT.failure();return new Detail(row(r),values,dependencies);}
 public Map<String,Object> getOptions(){access.require(ActionType.READ);return Map.of("dataSources",jdbc.query("SELECT DATA_SOURCE_ID,ALIAS_NM,DBMS_CD,DBMS_VERSION FROM AI_ADMIN_DATA_SOURCE ORDER BY ALIAS_NM,DATA_SOURCE_ID",(r,n)->Map.of("id",r.getString(1),"alias",Objects.toString(r.getString(2),""),"dbmsCode",r.getString(3),"dbmsVersion",Objects.toString(r.getString(4),""))),"timezones",Timezones.candidates(clock.zone()),"maskingTypes",List.of(),"maskingState","NOT_CONNECTED");}
 public List<Map<String,Object>> mappings(String key){return jdbc.queryForList("SELECT CLIENT_KEY AS \"clientKey\",MEMBER_ID::text AS \"memberId\",MEMBER_KIND AS \"kind\" FROM AI_ADMIN_CATALOG_MEMBER WHERE COMMAND_KEY=? ORDER BY MEMBER_ID",key);}
 public CatalogSource.Observation getResolvedObject(Map<String,Object> master){access.require(ActionType.READ);CatalogDefinition.known(master,CatalogDefinition.MASTER);var ds=owner.ds(Objects.toString(master.get("dataSourceId"),null));try{return source.observe("catalog-metadata",ds.key(),CatalogService.names(master));}catch(IllegalArgumentException failure){throw ManagedErrorCode.VALIDATION.failure();}}
 public CatalogSource.Observation getStructure(String id,String revision){var detail=getOne(id);if(!detail.row().get("revision").equals(revision))throw ManagedErrorCode.REVISION_CONFLICT.failure();return getResolvedObject(CatalogDefinition.map(detail.values().get("master")));}
 public Object revision(String id,String revision,String historyNo){access.require(ActionType.READ);if(historyNo==null){ManagedCommand.positive(revision);historyNo=jdbc.queryForObject("SELECT HISTORY_NO::text FROM AI_ADMIN_CATALOG_HIST WHERE CATALOG_ID=? AND RESULT_REVISION=?",String.class,ManagedCommand.positive(id),Long.valueOf(revision));}var event=owner.history().event(ManagedCommand.positive(historyNo));if(!event.ref().targetId().equals(id)||revision!=null&&!event.ref().revision().equals(revision))throw ManagedErrorCode.HISTORY_UNAVAILABLE.failure();return event;}
}
